/*
 * A209355  Sequence with each term appearing in runs of every length
 *          infinitely often.
 * https://oeis.org/A209355
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) is 0 if the position falls in the first half of a run (the
 *            one consisting of the integer t), and 1 otherwise. The sequence
 *            is generated by blocks k = 1,2,3,… where block k consists of the
 *            runs 1,1,2,2,…,k,k (each integer appears twice, each run having
 *            that length). The block k covers exactly...
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   C_block
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include "../utils/C_block.h"

seq_t a(idx_t n) {
    /* n>=1; return the n-th term (0 or 1) of A209355 */
    if (n == 0) return 0;          /* undefined but safe */

    /* ---- locate the block k that contains n ---- */
    idx_t k;
    idx_t low = 1, high = 1;
    while (C_block(high) < (unsigned __int128)n)
        high <<= 1;                 /* grow high until it covers n   */

    low = high >> 1;
    while (low + 1 < high) {
        idx_t mid = low + ((high - low) >> 1);
        if (C_block(mid) < (unsigned __int128)n)
            low = mid;
        else
            high = mid;
    }
    k = high;

    /* ---- offset within block k (1‑based) ---- */
    unsigned __int128 C_prev = (unsigned __int128)(k - 1) * k * (k + 1) / 3;
    idx_t offset = n - (idx_t)C_prev;          /* 1 <= offset <= k(k+1) */
    idx_t offset0 = offset - 1;                /* 0‑based within block   */

    /* ---- find t: smallest integer with t*(t+1) >= offset ---- */
    idx_t lo = 0, hi = offset;                /* t <= offset */
    while (lo + 1 < hi) {
        idx_t mid = lo + ((hi - lo) >> 1);
        unsigned __int128 prod = (unsigned __int128)mid * (mid + 1);
        if (prod >= (unsigned __int128)offset)
            hi = mid;
        else
            lo = mid;
    }
    idx_t t = hi;

    /* ---- decide if in first or second run of t ---- */
    unsigned __int128 t2 = (unsigned __int128)t * t;
    seq_t result = (offset0 < t2) ? (seq_t)0 : (seq_t)1;
    return result;
}
